/**
 * @typedef {[x: number, y: number, value: number]} HeatPoint
 * @typedef {Record<number, string>} HeatGradient Color stops in the 0..1 range, e.g. `{0.4: 'blue', 1: 'red'}`.
 * @typedef {HTMLCanvasElement | OffscreenCanvas} AnyCanvas
 */
export type HeatPoint = [x: number, y: number, value: number];
export type HeatGradient = Record<number, string>;
export type AnyCanvas = HTMLCanvasElement | OffscreenCanvas;
export default class SimpleHeat {
    _canvas: AnyCanvas;
    _ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D;
    _max: number;
    _data: HeatPoint[];
    _circle: HTMLCanvasElement | OffscreenCanvas | undefined;
    _r: number | undefined;
    _grad: Uint32Array<ArrayBuffer> | undefined;
    /** @param {AnyCanvas | string} canvas A canvas or the id of a canvas element. */
    constructor(canvas: AnyCanvas | string);
    /**
     * Set data points, replacing existing ones.
     * @param {HeatPoint[]} data
     */
    data(data: HeatPoint[]): this;
    /**
     * Set the value that maps to the full gradient color (1 by default).
     * @param {number} max
     */
    max(max: number): this;
    /**
     * Add a data point.
     * @param {HeatPoint} point
     */
    add(point: HeatPoint): this;
    /** Remove all data points. */
    clear(): this;
    /**
     * Set point radius and blur radius.
     * @param {number} r
     * @param {number} blur
     */
    radius(r?: number, blur?: number): this;
    /**
     * Set gradient colors.
     * @param {HeatGradient} grad
     */
    gradient(grad?: HeatGradient): this;
    /**
     * Draw the heatmap.
     * @param {number} minOpacity Minimum point opacity.
     */
    draw(minOpacity?: number): this;
}
